selector_to_html = {"a[href=\"#pyskyfire.network.blocks.PumpBlock.post_process\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.PumpBlock.post_process\">\n<span class=\"sig-name descname\"><span class=\"pre\">post_process</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signals</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The shaft power split by where it went, at the converged state.</p></dd>", "a[href=\"#pyskyfire.network.blocks.PumpBlock\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.PumpBlock\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.network.blocks.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PumpBlock</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_out</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">overcome</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_base</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">input_p</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">load_fraction</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_efficiency</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">medium</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mechanical_efficiency</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">disk_friction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">FluidBlock</span></code></p><p>Pump stage charged component by component.</p><p>The block raises inlet pressure to meet a target set by the load\n(sum of downstream pressure drops) and computes shaft power and outlet state.</p><p>Each loss is charged once, where it happens. The outlet is the impeller\noutlet, so a volute or diffuser after it is its own block and its loss is\npart of the load. The blades do <code class=\"docutils literal notranslate\"><span class=\"pre\">g*H/eta_h</span></code> of work on every kilogram,\nwith <code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_efficiency</span></code> the impeller\u2019s own. Disk friction on the\noutside of the wheel is added on top, and both end up as heat in the\nfluid. The mechanical efficiency then covers bearings and shaft seals,\nwhose heat leaves through the housing rather than the flow. No leakage is\nmodelled yet: every kilogram through the impeller is delivered.</p></dd>", "a[href=\"../engine_network/Station.html#pyskyfire.network.engine_network.Station\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.engine_network.Station\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.network.engine_network.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Station</span></span></dt><dd><p>Thermodynamic state container used by the engine network.</p></dd>", "a[href=\"#pyskyfire-network-blocks-pumpblock\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.network.blocks.PumpBlock<a class=\"headerlink\" href=\"#pyskyfire-network-blocks-pumpblock\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.network.blocks.PumpBlock.compute\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.PumpBlock.compute\">\n<span class=\"sig-name descname\"><span class=\"pre\">compute</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signals</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute outlet state and required pump power.</p><p class=\"rubric\">Notes</p><p>Temperature property calls are offset by <code class=\"docutils literal notranslate\"><span class=\"pre\">1e-3</span> <span class=\"pre\">K</span></code> to avoid\nsaturation-line singularities in CoolProp.</p></dd>", "a[href=\"#pyskyfire.network.blocks.PumpBlock._evaluate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.PumpBlock._evaluate\">\n<span class=\"sig-name descname\"><span class=\"pre\">_evaluate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signals</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
